static PyObject *
Composer_to_dict (ComposerObject *self, PyObject *Py_UNUSED (ignored))
{
  PyObject *r = _Composer_resolved (self);
  if (!r)
    return NULL;
  PyObject  *seglist  = PyTuple_GET_ITEM (r, 0); /* borrowed */
  Py_ssize_t nseg     = PyList_GET_SIZE (seglist);
  PyObject  *segs_out = PyList_New (nseg);
  if (!segs_out)
    goto fail;
  for (Py_ssize_t i = 0; i < nseg; i++)
    {
      PyObject *seg = PyList_GET_ITEM (seglist, i); /* borrowed */
      PyObject *sd  = _Composer_obj_to_dict (seg, _Composer_seg_keys);
      if (!sd)
        goto fail_segs;
      PyObject *srcs = PyObject_GetAttrString (seg, "sources");
      if (!srcs)
        {
          Py_DECREF (sd);
          goto fail_segs;
        }
      Py_ssize_t nsrc    = PyList_GET_SIZE (srcs);
      PyObject  *src_out = PyList_New (nsrc);
      if (!src_out)
        {
          Py_DECREF (srcs);
          Py_DECREF (sd);
          goto fail_segs;
        }
      for (Py_ssize_t k = 0; k < nsrc; k++)
        {
          PyObject *kd = _Composer_obj_to_dict (PyList_GET_ITEM (srcs, k),
                                                _Composer_src_keys);
          if (!kd)
            {
              Py_DECREF (src_out);
              Py_DECREF (srcs);
              Py_DECREF (sd);
              goto fail_segs;
            }
          PyList_SET_ITEM (src_out, k, kd); /* steals */
        }
      Py_DECREF (srcs);
      int rc = PyDict_SetItemString (sd, "sources", src_out);
      Py_DECREF (src_out);
      if (rc < 0)
        {
          Py_DECREF (sd);
          goto fail_segs;
        }
      PyList_SET_ITEM (segs_out, i, sd); /* steals */
    }
  {
    PyObject *out = Py_BuildValue (
        "{s:O,s:O,s:N}", "repeat", PyTuple_GET_ITEM (r, 1), "continuous",
        PyTuple_GET_ITEM (r, 2), "segments", segs_out);
    Py_DECREF (r);
    return out; /* Py_BuildValue stole segs_out via N */
  }
fail_segs:
  Py_DECREF (segs_out);
fail:
  Py_DECREF (r);
  return NULL;
}

static PyObject *
Composer__draws_json (ComposerObject *self, PyObject *Py_UNUSED (ignored))
{
  if (self->destroyed)
    {
      PyErr_SetString (PyExc_RuntimeError, "composer already closed");
      return NULL;
    }

  size_t               _n;
  int                  _rep = 0, _cont = 0;
  const wfm_segment_t *segs
      = dp_wfm_compose_segments (self->state, &_n, &_rep, &_cont);
  char *_js = dp_wfm_draws_json (segs, _n);
  if (!_js)
    {
      PyErr_SetString (PyExc_RuntimeError, "dp_wfm_draws_json failed");
      return NULL;
    }
  PyObject *_s = PyUnicode_FromString (_js);
  free (_js);
  return _s;
}

static PyObject *
Composer_to_sigmf (ComposerObject *self, PyObject *args, PyObject *kwds)
{
  if (self->destroyed)
    {
      PyErr_SetString (PyExc_RuntimeError, "composer already closed");
      return NULL;
    }
  const char  *sample_type = "cf32";
  const char  *endian      = "le";
  double       fs          = 0.0;
  double       fc          = 0.0;
  double       t0          = 0.0;
  static char *kwlist[] = { "sample_type", "endian", "fs", "fc", "t0", NULL };
  if (!PyArg_ParseTupleAndKeywords (args, kwds, "|ssddd", kwlist, &sample_type,
                                    &endian, &fs, &fc, &t0))
    return NULL;
  int _e_sample_type = _enum_index (_enum_stype, sample_type);
  if (_e_sample_type < 0)
    {
      PyErr_Format (PyExc_ValueError,
                    "invalid sample_type '%s' (choices: cf32, cf64, ci32, "
                    "ci16, ci8, f32, f64, i32, i16, i8)",
                    sample_type);
      return NULL;
    }
  int _e_endian = _enum_index (_enum_endian, endian);
  if (_e_endian < 0)
    {
      PyErr_Format (PyExc_ValueError, "invalid endian '%s' (choices: le, be)",
                    endian);
      return NULL;
    }
  size_t               _n;
  int                  _rep = 0, _cont = 0;
  const wfm_segment_t *segs
      = dp_wfm_compose_segments (self->state, &_n, &_rep, &_cont);
  char *_js = dp_wfm_sigmf_meta_json (_e_sample_type, _e_endian, fs, fc, t0,
                                      segs, _n);
  if (!_js)
    {
      PyErr_SetString (PyExc_RuntimeError, "dp_wfm_sigmf_meta_json failed");
      return NULL;
    }
  PyObject *_s = PyUnicode_FromString (_js);
  free (_js);
  return _s;
}
